GameMessage::~GameMessage()
{
    if (m_argList) {
        GameMessageArgument *node = m_argList;
        do {
            GameMessageArgument *next = node->m_next;
            ::delete node;
            node = next;
        } while (node);
    }
    m_argList = 0;
    if (m_list) m_list->removeMessage(this);
}

// FUNCTION: BFME2 0x0030F4EA size=34 name=?getArgument@GameMessage@@QBEPBTGameMessageArgumentType@@H@Z evidence=N:ledger
const GameMessageArgumentType *GameMessage::getArgument(int argIndex) const
{
	int i = 0;
	for (GameMessageArgument *gameMessageArgument = m_argList; gameMessageArgument; gameMessageArgument = gameMessageArgument->m_next, i++)
		if (i == argIndex)
			return &gameMessageArgument->m_data;

	static const GameMessageArgumentType emptyArgument = { 0 };
	return &emptyArgument;
}

// FUNCTION: BFME2 0x0030F50C size=48 name=?getArgumentDataType@GameMessage@@QAE?AW4GameMessageArgumentDataType@@H@Z evidence=N:ledger
GameMessageArgumentDataType GameMessage::getArgumentDataType( Int argIndex )
{
	if (argIndex >= m_argCount) {
		return ARGUMENTDATATYPE_UNKNOWN;
	}
	int i=0;
	for (GameMessageArgument *gameMessageArgument = m_argList; gameMessageArgument && (i < argIndex); gameMessageArgument=gameMessageArgument->m_next, ++i );

	if (gameMessageArgument != NULL)
	{
		return gameMessageArgument->m_type;
	}
	return ARGUMENTDATATYPE_UNKNOWN;
}

