// FUNCTION: BFME2 0x0030F5D2 size=50 name=?appendMessage@GameMessageList@@UAEXPAVGameMessage@@@Z evidence=N:ledger
void GameMessageList::appendMessage(GameMessage *msg)
{
	if (!msg)
		return;
	msg->m_next = 0;
	if (m_lastMessage)
	{
		m_lastMessage->m_next = msg;
		msg->m_prev = m_lastMessage;
		m_lastMessage = msg;
	}
	else
	{
		m_firstMessage = msg;
		m_lastMessage = msg;
		msg->m_prev = 0;
	}
	msg->m_list = this;
}

// FUNCTION: BFME2 0x0030F604 size=62 name=?insertMessage@GameMessageList@@UAEXPAVGameMessage@@0@Z evidence=N:ledger
void GameMessageList::insertMessage(GameMessage *msg, GameMessage *messageToInsertAfter)
{
	if (messageToInsertAfter)
	{
		msg->m_next = messageToInsertAfter->m_next;
		msg->m_prev = messageToInsertAfter;
		messageToInsertAfter->m_next = msg;
	}
	else
	{
		msg->m_next = m_firstMessage;
		msg->m_prev = 0;
		m_firstMessage = msg;
	}
	if (msg->m_next)
		((GameMessage *)msg->m_next)->m_prev = msg;
	else
		m_lastMessage = msg;
	msg->m_list = this;
}

// FUNCTION: BFME2 0x0030F642 size=55 name=?rva0030F642@Rva0030F642@@QAEXPAURva0030F642Node@@@Z evidence=?:placeholder
void GameMessageList::removeMessage( GameMessage *msg )
{
	// Unlink from the neighbours, moving the list's end pointers when the message was at an end.
	if (msg->next())
		msg->next()->friend_setPrev(msg->prev());
	else
		m_lastMessage = msg->prev();

	if (msg->prev())
		msg->prev()->friend_setNext(msg->next());
	else
		m_firstMessage = msg->next();

	msg->friend_setList(NULL);
}

// FUNCTION: BFME2 0x0030F679 size=30 name=?rva0030F679@Rva0030F642@@QBE_NH@Z evidence=?:placeholder
Bool GameMessageList::containsMessageOfType( GameMessage::Type type )
{
	for (GameMessage *cursor = getFirstMessage(); cursor; cursor = cursor->next()) {
		if (cursor->getType() == type)
			return true;
	}
	return false;
}

