// FUNCTION: BFME2 0x0030F738 size=159 name=?attachTranslator@MessageStream@@QAEIPAVGameMessageTranslator@@I@Z evidence=N:ledger
unsigned int MessageStream::attachTranslator(GameMessageTranslator *translator, unsigned int priority)
{
	TranslatorData *entry = new TranslatorData;
	TranslatorData *later;

	entry->m_translator = translator;
	entry->m_priority = priority;
	entry->m_id = m_nextTranslatorID++;

	// First entry on an empty chain.
	if (m_firstTranslator == 0)
	{
		entry->m_prev = 0;
		entry->m_next = 0;
		m_firstTranslator = entry;
		m_lastTranslator = entry;
		return entry->m_id;
	}

	// The chain is ordered by priority: find the first translator with a larger priority value.
	for (later = (TranslatorData *)m_firstTranslator; later; later = later->m_next)
		if (later->m_priority > entry->m_priority)
			break;

	if (later)
	{
		if (later->m_prev)
		{
			later->m_prev->m_next = entry;
			entry->m_prev = later->m_prev;
			entry->m_next = later;
			later->m_prev = entry;
		}
		else
		{
			entry->m_prev = 0;
			entry->m_next = (TranslatorData *)m_firstTranslator;
			((TranslatorData *)m_firstTranslator)->m_prev = entry;
			m_firstTranslator = entry;
		}
	}
	else
	{
		((TranslatorData *)m_lastTranslator)->m_next = entry;
		entry->m_prev = (TranslatorData *)m_lastTranslator;
		entry->m_next = 0;
		m_lastTranslator = entry;
	}

	return entry->m_id;
}

// FUNCTION: BFME2 0x0030F7D7 size=28 name=?findTranslator@MessageStream@@QAEPAVGameMessageTranslator@@I@Z evidence=N:ledger
GameMessageTranslator *MessageStream::findTranslator(unsigned int id)
{
	TranslatorData *candidate;

	for (candidate = (TranslatorData *)m_firstTranslator; candidate; candidate = candidate->m_next)
	{
		if (candidate->m_id == id)
			return candidate->m_translator;
	}

	return 0;
}

// FUNCTION: BFME2 0x0030F7F3 size=79 name=?removeTranslator@MessageStream@@QAEXI@Z evidence=N:ledger
void MessageStream::removeTranslator(unsigned int id)
{
	TranslatorData *translatorData;

	for (translatorData = (TranslatorData *)m_firstTranslator; translatorData; translatorData = translatorData->m_next)
	{
		if (translatorData->m_id == id)
		{
			if (translatorData->m_prev)
				translatorData->m_prev->m_next = translatorData->m_next;
			else
				m_firstTranslator = translatorData->m_next;

			if (translatorData->m_next)
				translatorData->m_next->m_prev = translatorData->m_prev;
			else
				m_lastTranslator = translatorData->m_prev;

			delete translatorData;
			break;
		}
	}
}

