GameMessageArgument *GameMessage::allocArg(void)
{
	GameMessageArgument *slot = new GameMessageArgument;

	if (m_argTail)
		m_argTail->m_next = slot;
	else
	{
		m_argList = slot;
		m_argTail = slot;
	}

	slot->m_next = 0;
	m_argTail = slot;

	m_argCount++;

	return slot;
}

